3	import org.junit.jupiter.api.Test;
4	
5	import java.util.List;
6	import java.util.Map;
7	import java.util.TreeMap;
8	import java.util.concurrent.atomic.AtomicLong;
9	
10	import static org.assertj.core.api.Assertions.assertThat;
11	
12	/**
13	 * 锁定解析器单元测试：回溯、环依赖、撤回版本过滤与字典序解析顺序。
14	 */
15	class LockResolverTest {
16	
17	    /** 测试用快照构造器：按 name -> 版本（版本号，是否撤回，依赖列表）组织，版本降序排列。 */
18	    private static RepositorySnapshot snapshot(long version, Object... groups) {
19	        Map<String, List<ArtifactVersion>> map = new TreeMap<>();
20	        AtomicLong id = new AtomicLong(1);
21	        for (int i = 0; i < groups.length; i += 2) {
22	            String name = (String) groups[i];
23	            @SuppressWarnings("unchecked")
24	            List<TestVersion> versions = (List<TestVersion>) groups[i + 1];
25	            List<ArtifactVersion> list = versions.stream()
26	                    .map(v -> new ArtifactVersion(id.getAndIncrement(), name, v.version(),
27	                            v.withdrawn(), v.deps()))
28	                    .toList();
29	            map.put(name, list);
30	        }
31	        return new RepositorySnapshot(version, map);
32	    }
33	
34	    private record TestVersion(int version, boolean withdrawn, List<DependencyRange> deps) {
35	    }
36	
37	    private static TestVersion v(int version, DependencyRange... deps) {
38	        return new TestVersion(version, false, List.of(deps));
39	    }
40	
41	    private static TestVersion w(int version, DependencyRange... deps) {
42	        return new TestVersion(version, true, List.of(deps));
43	    }
44	
45	    private static DependencyRange dep(String name, int min, int max) {
46	        return new DependencyRange(name, min, max);
47	    }
48	
49	    @Test
50	    void resolvesSingleRootWithoutDependencies() {
51	        RepositorySnapshot s = snapshot(0, "app", List.of(v(1)));
52	        assertThat(LockResolver.resolve(s, "app", 1))
53	                .isEqualTo(Map.of("app", 1));
54	    }
55	
56	    @Test
57	    void requiresBacktrackingWhenHighestCandidateConflictsLater() {
58	        // app:1 -> B[1,2] 且 C[1,1]；B2 -> C[2,2]（与 C1 冲突），必须回退到 B1。
59	        RepositorySnapshot s = snapshot(0,
60	                "app", List.of(v(1, dep("b", 1, 2), dep("c", 1, 1))),
61	                "b", List.of(v(2, dep("c", 2, 2)), v(1)),
62	                "c", List.of(v(1)));
63	
64	        Map<String, Integer> result = LockResolver.resolve(s, "app", 1);
65	        assertThat(result).isNotNull();
66	        assertThat(result).containsEntry("app", 1).containsEntry("b", 1).containsEntry("c", 1);
67	    }
68	
69	    @Test
70	    void cannotGreedilyTakeHighestVersionAcrossMultipleLevels() {
71	        // app -> a[1,2]；a2 -> b[2,2]，a1 -> b[1,1]；b2 已撤回，b1 有效。
72	        // 贪心取 a2 将失败，必须回退到 a1/b1。
