    @Test
    void optionalDependencyWithoutAnyCompatibleVersionIsSkippedButLockSucceeds() {
        // 仅有 ghost 但区间不匹配（或不存在）：SKIPPED/NO_COMPATIBLE_CANDIDATE，锁定不失败。
        service.registerArtifact(requestId(),
