                artifact("app", 1, dep("lib", 1, 2), opt("plugin", 1, 1)));
        service.registerArtifact(requestId(), artifact("lib", 2, dep("app", 1, 1)));
        service.registerArtifact(requestId(), artifact("lib", 1));
